ctx.strokeStyle='#65f6ce24';ctx.lineWidth=2;ctx.setLineDash([12,18]);ctx.beginPath();ctx.arc(0,0,RADIUS,0,TAU);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#65f6ce08';ctx.lineWidth=35;ctx.beginPath();ctx.arc(0,0,RADIUS+20,0,TAU);ctx.stroke();ctx.lineWidth=1;
