ctx.save();ctx.lineCap='round';for(const b of bullets){glow(b.color,12);ctx.strokeStyle=b.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x-b.vx*.019,b.y-b.vy*.019);ctx.stroke()}for(const b of enemyBullets){glow(b.color,9);ctx.fillStyle=b.color;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,TAU);ctx.fill()}ctx.restore();
if(player.orbit){ctx.strokeStyle='#65f6ce12';ctx.beginPath();ctx.arc(player.x,player.y,76,0,TAU);ctx.stroke();for(let i=0;i<player.orbit;i++){const a=time*3+i*TAU/player.orbit;ctx.save();glow('#65f6ce',12);poly(player.x+Math.cos(a)*76,player.y+Math.sin(a)*76,11,3,a+Math.PI/2,'#aaffdf','#65f6ce66');ctx.restore()}}
